// === Tab: mySketch ===
let canvasSize = 1000;
let COLORS = ["#fff12d1f","#e41cfa27","#00ccff3f"];
let objs = [];

let objCount = 200;
let weight = 0;
let rLimMAxRatio = 0.6;
let rLimMinRatio = 0.3;

let alphaSpeed = 2;
let sound, fft;
let spots = [];


function setup() {
  createCanvas(canvasSize, canvasSize);
  angleMode(DEGREES);

  //円状に敷き詰め
  var trycount = 0;
  while(objs.length < objCount){

    //var angle = random(360);
    //var r = canvasSize*random(0.45);
    //var x = r*cos(angle);
    //var y = r*sin(angle);  
    var x = random(-canvasSize*0.5,canvasSize*0.5);
    var y = random(-canvasSize*0.5,canvasSize*0.5);

    var rLim = canvasSize*0.4;//(canvasSize*0.45-r);
    // check hit
    var hitresult = false;
    for(let i = 0; i < objs.length; i++){
      let o = objs[i];
      let distance = dist(x, y, o.x, o.y);

      if(distance + rLimMinRatio*canvasSize < o.rlim ){
        hitresult = true;
        break;
      }
      else{
        rLim = min(rLim,distance - o.rlim)
      }
    }

    if(!hitresult){
      rLim = min(canvasSize*rLimMAxRatio,rLim);
      corner = int(random(10,50));
      var clr = random(COLORS);
      objs.push(new mPoly(x,y,rLim,corner,0,clr));
      spots.push({x:x,y:y,lim:rLim,corner, clr});

    }

    trycount++;
    if(trycount > 10000){break;}
  }
}

function draw() {
  translate(canvasSize*0.5,canvasSize*0.5)
  blendMode(BLEND);
  background(10);



  objs.forEach(o =>{
    o.draw();
  })


  objs = objs.filter(o => o.a > 0);


}



function mPoly(x, y, Rlim,corner,rt= 0,clr = "#ffffff27") {
  this.x = x;
  this.y = y;
  this.rlim = Rlim;
  this.r = Rlim;
  //this.color = color(random(COLORS));
  this.a = 255;
  this.weight = 0;
  this.corner = corner;
  this.rt = rt;
  this.clr = clr;

  this.draw = function() {
    push();
    fill(this.clr)
    stroke(255,this.a);
    translate(this.x, this.y);
    rotate(this.rt);
    circle(0,0,10);

    beginShape();

    for(let i = 0; i < this.corner; i++){
      let px = (this.r ) * cos(i*360/this.corner);//-10*noise(this.x+i,this.r);
      let py = (this.r ) * sin(i*360/this.corner);//-10*noise(this.y+i,this.r);

      vertex(0,0);
      vertex(px,py);     
    }

    endShape(CLOSE);
    //stroke(0);
    //circle(0,0,this.rlim*2);
    pop();

    this.rt += alphaSpeed*0.1;
  };
}

